"""Synthetic-only tests; no benchmark predictions are generated by pytest."""
import json
import pytest
from src.data.deterministic_sampler import choose_indices
from src.evaluation.freeze_baseline import seal, verify_freeze
from src.evaluation.final_crf import prediction_record, select_split, reserve_once, replay
from src.evaluation.metrics import StrictMetrics
from src.utils.io import file_hash, write_json, canonical


def test_frozen_config_tampering(tmp_path):
    config = tmp_path / "config.yaml"
    config.write_text("c1: 0.1\n")
    manifest = tmp_path / "freeze.json"
    write_json(manifest, seal({"files": {str(config): file_hash(config)}}))
    verify_freeze(manifest)
    config.write_text("c1: 0.2\n")
    with pytest.raises(ValueError, match="Frozen artifact changed"):
        verify_freeze(manifest)


def test_freeze_manifest_tampering(tmp_path):
    manifest = tmp_path / "freeze.json"
    envelope = seal({"files": {}, "seed": 42})
    envelope["payload"]["seed"] = 99
    write_json(manifest, envelope)
    with pytest.raises(ValueError, match="manifest checksum"):
        verify_freeze(manifest)


@pytest.mark.parametrize("split", ["train_clean", "validation_clean", "../test_clean"])
def test_final_split_rejection(split):
    with pytest.raises(ValueError):
        select_split("data", split)


@pytest.mark.parametrize("split", ["test_clean", "official_test"])
def test_final_split_selection(split):
    assert select_split("data", split).as_posix() == f"data/{split}.jsonl"


@pytest.mark.parametrize("split", ["validation", "test"])
def test_test_data_cannot_train(split):
    rows = [{"source_split": split, "source_index": 0, "tokens": ["नाम"], "labels": ["B-PER"]}]
    with pytest.raises(ValueError, match="Only train_clean"):
        choose_indices(rows, 3, 42)


def test_prediction_schema_and_replay(tmp_path):
    row = {"source_split": "test", "source_index": 7, "tokens": ["नई", "दिल्ली"], "labels": ["B-LOC", "I-LOC"]}
    result = prediction_record(row, ["B-LOC", "O"], "test_clean", "synthetic")
    assert result["source_id"] == "naamapadam:hi:test:7"
    assert result["gold_spans"] == [(0, 2, "LOC")]
    path = tmp_path / "predictions.jsonl"
    path.write_text(canonical(result) + "\n")
    first, count = replay(path)
    assert count == 1 and replay(path) == (first, count)
    direct = StrictMetrics()
    direct.add(row["labels"], ["B-LOC", "O"])
    assert first == direct.result()
    assert first["strict_entity_micro_f1"] == 0


def test_empty_official_prediction(tmp_path):
    item = prediction_record({"source_split": "test", "source_index": 481, "tokens": [], "labels": []}, [], "official_test", "synthetic")
    assert item["gold_spans"] == [] and item["predicted_labels"] == []


def test_prediction_wrong_source():
    with pytest.raises(ValueError):
        prediction_record({"source_split": "train", "source_index": 0, "tokens": [], "labels": []}, [], "test_clean", "synthetic")


def test_one_shot_guard(tmp_path):
    marker = tmp_path / "started.json"
    reserve_once(marker)
    with pytest.raises(FileExistsError):
        reserve_once(marker)
